async function main() {
  const dir = process.argv[2];
  if (!dir) { console.error("Usage: node generateHar.js <http-log-dir> [output.har]"); process.exit(1); }
  const resolved = path.resolve(dir);
  const out = process.argv[3] ? path.resolve(process.argv[3]) : path.join(resolved, "requests.har");
  const files = await fs.readdir(resolved);
  const reqs = new Map(), resps = new Map(), seqs = new Map(), msgs = new Map(), sseChunks = new Map();
  for (const f of files) {
    if (f.includes("_request_messages_dump_")) { const d = JSON.parse(await fs.readFile(path.join(resolved, f), "utf8")); msgs.set(f.match(/^(\\d+)/)[1], d); continue; }
    if (f.includes("_response_sse_chunks_")) { const d = await fs.readFile(path.join(resolved, f), "utf8"); sseChunks.set(f.match(/^(\\d+)/)[1], d); continue; }
    let m = f.match(/^(\\d+)_request_(.+)\\.json$/);
    if (m) { const d = JSON.parse(await fs.readFile(path.join(resolved, f), "utf8")); reqs.set(d.requestId, d); seqs.set(d.requestId, Math.min(+m[1], seqs.get(d.requestId) ?? Infinity)); continue; }
    m = f.match(/^(\\d+)_response_headers_(.+)\\.json$/);
    if (m) { const d = JSON.parse(await fs.readFile(path.join(resolved, f), "utf8")); resps.set(d.requestId, d); }
  }
  const ids = [...reqs.keys()].sort((a, b) => (seqs.get(a) ?? 0) - (seqs.get(b) ?? 0));
  const entries = ids.map(id => { const seq = String(seqs.get(id)).padStart(6, "0"); return buildEntry(reqs.get(id), resps.get(id), msgs.get(seq), sseChunks.get(seq)); });
  const har = { log: { version: "1.2", creator: { name: "copilot-language-server", version: "1.0" }, entries } };
  await fs.writeFile(out, JSON.stringify(har, null, 2), "utf8");
  console.log("HAR written: " + out + " (" + entries.length + " entries)");
}

